# Keys a caller (the frontend) may override on an outbound request context.
OVERRIDABLE = frozenset({"networkId", "version", "bppId", "bppUri", "ttl", "schemaContext"})
BPP_KEYS = ("bppId", "bppUri")


@dataclass(frozen=True)
