        <CreateReferralContent
          encounter={encounter}
          patientId={encounter ? encounter.patient.id : patientId}
          facilityId={encounter?.facility.id ?? facilityId}
          setIsPending={setIsPending}
          onCancel={() => setOpen(false)}
          onCreated={(referral) => {
            setOpen(false);
            setIsPending(false);
            onCreated?.(referral);
          }}
        />
      )}
    </Dialog>
