const PAGE_SIZE = 20;

interface DestinationOption {
  id: string;
  name: string;
}

interface SearchPage {
  search: string;
  offset: number;
  signal: AbortSignal;
}

interface DestinationComboboxProps<T extends DestinationOption> {
  label: string;
  placeholder: string;
  searchPlaceholder: string;
  emptyMessage: string;
  selected: T | null;
  onSelect: (option: T) => void;
  queryKey: QueryKey;
  fetchOptions: (page: SearchPage) => Promise<PaginatedResponse<T>>;
  disabled?: boolean;
  renderOption?: (option: T) => ReactNode;
}

function DestinationCombobox<T extends DestinationOption>({
  label,
  placeholder,
  searchPlaceholder,
  emptyMessage,
  selected,
  onSelect,
  queryKey,
  fetchOptions,
  disabled,
  renderOption,
}: DestinationComboboxProps<T>) {
  const { t } = useTranslation();
  const id = useId();
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");
  const isMobile = useBreakpoints({ default: true, sm: false });
  const optionsQuery = useInfiniteQuery({
    queryKey: [...queryKey, search.trim()],
    queryFn: ({ pageParam, signal }) =>
      fetchOptions({ search: search.trim(), offset: pageParam, signal }),
    initialPageParam: 0,
    getNextPageParam: (lastPage, pages) => {
      const offset = pages.reduce(
        (count, page) => count + page.results.length,
        0,
      );
      return lastPage.results.length > 0 && offset < lastPage.count
        ? offset
        : undefined;
    },
    enabled: open && !disabled,
    retry: false,
  });
  const options = Array.from(
    new Map(
      optionsQuery.data?.pages.flatMap((page) =>
        page.results.map((option) => [option.id, option] as const),
      ),
    ).values(),
  );
  const hasPageError =
    optionsQuery.isError && !optionsQuery.isFetchNextPageError;

  const handleOpenChange = (nextOpen: boolean) => {
    setOpen(nextOpen);
    if (!nextOpen) setSearch("");
  };
  const trigger = (
    <Button
      id={id}
      type="button"
      variant="outline"
      role="combobox"
      aria-labelledby={`${id}-label`}
      aria-expanded={open}
      disabled={disabled}
      className="w-full min-w-0 justify-between font-normal tracking-normal shadow-none"
    >
      <span
        className={cn(
          "w-0 min-w-0 flex-1 truncate text-left",
          !selected && "text-muted-foreground",
        )}
      >
        {selected?.name ?? placeholder}
      </span>
      <ChevronsUpDown className="size-4 opacity-50" aria-hidden="true" />
    </Button>
  );
  const content = (
    <Command shouldFilter={false} className="bg-background text-foreground">
      <CommandInput
        aria-label={searchPlaceholder}
        placeholder={searchPlaceholder}
        value={search}
        onValueChange={setSearch}
        wrapperClassName="border-b border-gray-100 md:p-2 shadow-xs md:pt-2"
        className="text-base sm:text-sm"
      />
      <CommandList
        className="scrollbar-gutter-auto sm:max-h-[min(320px,45dvh)]"
        aria-busy={optionsQuery.isFetching}
      >
        {optionsQuery.isPending ? (
          <div
            role="status"
            className="flex items-center justify-center gap-2 p-4 text-sm text-muted-foreground"
          >
            <Spinner className="size-4 animate-spin" aria-hidden="true" />
            {t("loading")}
          </div>
        ) : hasPageError ? (
          <div role="alert" className="space-y-2 p-4 text-sm">
            <p>{t("referral_picker_load_error")}</p>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => optionsQuery.refetch()}
            >
              {t("try_again")}
            </Button>
          </div>
        ) : options.length === 0 ? (
          <div
            role="status"
            className="p-4 text-center text-sm text-muted-foreground"
          >
            {emptyMessage}
          </div>
        ) : (
          <CommandGroup>
            {options.map((option) => (
              <CommandItem
                key={option.id}
                value={option.id}
                aria-label={renderOption ? undefined : option.name}
                onSelect={() => {
                  onSelect(option);
                  handleOpenChange(false);
                }}
                className="items-start gap-2 py-2"
              >
                <Check
                  className={cn(
                    "mt-0.5 size-4 shrink-0",
                    selected?.id !== option.id && "opacity-0",
                  )}
                  aria-hidden="true"
                />
                {renderOption ? (
                  renderOption(option)
                ) : (
                  <span className="min-w-0 break-words">{option.name}</span>
                )}
              </CommandItem>
            ))}
          </CommandGroup>
        )}
      </CommandList>
      {!hasPageError &&
        (optionsQuery.hasNextPage || optionsQuery.isFetchNextPageError) && (
          <div className="border-t border-border p-2">
            {optionsQuery.isFetchNextPageError && (
              <p role="alert" className="mb-2 text-sm text-muted-foreground">
                {t("referral_picker_load_error")}
              </p>
            )}
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="w-full shadow-none"
              disabled={optionsQuery.isFetching}
              onClick={() => optionsQuery.fetchNextPage()}
            >
              {optionsQuery.isFetchingNextPage && (
                <Spinner className="size-4 animate-spin" aria-hidden="true" />
              )}
              {t(
                optionsQuery.isFetchNextPageError
                  ? "try_again"
                  : "referral_picker_load_more",
              )}
            </Button>
          </div>
        )}
    </Command>
  );

  return (
    <Field className="min-w-0">
      <FieldLabel id={`${id}-label`} htmlFor={id}>
        {label}
      </FieldLabel>
      {isMobile ? (
        <Drawer open={open} onOpenChange={handleOpenChange}>
          <DrawerTrigger asChild>{trigger}</DrawerTrigger>
          <DrawerContent
            aria-describedby={undefined}
            height="fixed"
            className="p-1.5"
          >
            <DrawerHeader showCloseButton>
              <DrawerTitle>{label}</DrawerTitle>
            </DrawerHeader>
            <div className="flex min-h-0 flex-1 flex-col pb-[env(safe-area-inset-bottom)]">
              {content}
            </div>
          </DrawerContent>
        </Drawer>
      ) : (
        <Popover open={open} onOpenChange={handleOpenChange} modal>
          <PopoverTrigger asChild>{trigger}</PopoverTrigger>
          <PopoverContent
            align="start"
            className="w-[var(--anchor-width)] max-w-[calc(100vw-2rem)] overflow-hidden border-border bg-background p-0 text-foreground"
          >
            {content}
          </PopoverContent>
        </Popover>
      )}
    </Field>
  );
}

