import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";

import { isAwaitingCallback, isFailedTransaction } from "@/types/ccn/ccn";

function statusGroup(status: string) {
  if (isFailedTransaction(status)) return "failed";
  if (status === "QUEUED") return "queued";
  if (status === "ON_CONFIRM") return "confirmed";
  if (isAwaitingCallback(status)) return "awaiting";
  return "responded";
}

const VARIANTS = {
  failed: "destructive",
  queued: "neutral",
  awaiting: "warning",
  confirmed: "success",
  responded: "info",
} as const;

export function BecknTransactionStatusBadge({ status }: { status: string }) {
  const { t } = useTranslation();
  const group = statusGroup(status);
  return (
    <Badge variant={VARIANTS[group]} size="sm" dot title={status}>
      {t(`ccn_transaction_status__${group}`)}
      <span className="font-mono text-[0.65rem] opacity-70">{status}</span>
    </Badge>
  );
}

import { useMutation, useQuery } from "@tanstack/react-query";
import { Network, RefreshCw } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { BecknTransactionStatusBadge } from "@/components/Referral/network/BecknTransactionStatusBadge";
import { NETWORK_POLL_INTERVAL_MS } from "@/components/Referral/network/networkReferral";
import { useIsNetworkReferral } from "@/components/Referral/network/ReferralNetworkBadge";

import { isAwaitingCallback, isFailedTransaction } from "@/types/ccn/ccn";
import { ccnReferralApi } from "@/types/ccn/ccnApi";
import { ReferralRead } from "@/types/emr/referral/referral";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { HTTPError } from "@/Utils/request/types";
import { formatDateTime } from "@/Utils/utils";

/**
 * Network transaction of a referral raised in Care on a network availability.
 * The plugin opens that transaction with the referral id as `transaction_id`.
 */
export function ReferralNetworkStatus({ referral }: { referral: ReferralRead }) {
  const { t } = useTranslation();
  const isNetwork = useIsNetworkReferral(referral.availability);
  const transactionQuery = useQuery({
    queryKey: ["ccn", "referral", "transaction", referral.id],
    queryFn: query(ccnReferralApi.get, {
      pathParams: { transactionId: referral.id },
      silent: true,
    }),
    enabled: isNetwork,
    retry: false,
    refetchInterval: (q) =>
      isAwaitingCallback(q.state.data?.status) ? NETWORK_POLL_INTERVAL_MS : false,
  });
  const statusMutation = useMutation({
    mutationFn: mutate(ccnReferralApi.status, {
      pathParams: { transactionId: referral.id },
    }),
    onSuccess: () => transactionQuery.refetch(),
  });
  if (!isNetwork) return null;
  const transaction = transactionQuery.data;
  const notLinked =
    transactionQuery.error instanceof HTTPError &&
    transactionQuery.error.status === 404;

  return (
    <section
      aria-label={t("ccn_network_status")}
      className="space-y-3 rounded-lg border border-border bg-background p-4"
      data-cy="referral-network-status"
    >
      <div className="flex items-center justify-between gap-2">
        <h2 className="flex items-center gap-2 text-sm font-semibold">
          <Network className="size-4" aria-hidden="true" />
          {t("ccn_network_status")}
        </h2>
        {transaction && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            disabled={
              statusMutation.isPending || isAwaitingCallback(transaction.status)
            }
            onClick={() => statusMutation.mutate({})}
          >
            <RefreshCw
              aria-hidden="true"
              className={
                statusMutation.isPending ? "size-4 animate-spin" : "size-4"
              }
            />
            {t("ccn_request_status")}
          </Button>
        )}
      </div>
      {transactionQuery.isLoading && (
        <p role="status" className="text-sm text-muted-foreground">
          {t("loading")}
        </p>
      )}
      {notLinked && (
        <p className="text-sm text-muted-foreground">
          {t("ccn_transaction_not_linked")}
        </p>
      )}
      {transactionQuery.isError && !notLinked && (
        <p role="alert" className="text-sm text-destructive">
          {t("ccn_network_unavailable")}
        </p>
      )}
      {transaction && (
        <dl className="grid gap-2 text-sm">
          <div>
            <dt className="text-muted-foreground">{t("status")}</dt>
            <dd className="mt-1">
              <BecknTransactionStatusBadge status={transaction.status} />
            </dd>
          </div>
          {isFailedTransaction(transaction.status) &&
            transaction.last_error && (
              <div role="alert">
                <dt className="text-muted-foreground">{t("ccn_last_error")}</dt>
                <dd className="mt-1 break-words text-destructive">
                  {transaction.last_error.message ??
                    transaction.last_error.code}
                </dd>
              </div>
            )}
          {transaction.counterparty_id && (
            <div>
              <dt className="text-muted-foreground">
                {t("ccn_counterparty")}
              </dt>
              <dd className="mt-1 break-all">{transaction.counterparty_id}</dd>
            </div>
          )}
          {transaction.contract_id && (
            <div>
              <dt className="text-muted-foreground">{t("ccn_contract_id")}</dt>
              <dd className="mt-1 break-all font-mono text-xs">
                {transaction.contract_id}
              </dd>
            </div>
          )}
          {transaction.actions.length > 0 && (
            <div>
              <dt className="text-muted-foreground">
                {t("ccn_network_activity")}
              </dt>
              <dd className="mt-1 break-words font-mono text-xs">
                {transaction.actions.join(" → ")}
              </dd>
            </div>
          )}
          {transaction.modified_date && (
            <div>
              <dt className="text-muted-foreground">{t("last_modified")}</dt>
              <dd className="mt-1">
                {formatDateTime(transaction.modified_date)}
              </dd>
            </div>
          )}
        </dl>
      )}
    </section>
  );
}

